mapper.select:
select u.user_id from sys_user u
inner join sys_user_role sur
    on u.user_id = sur.user_id and sur.role_id = #{roleId}

mapper.update:
UPDATE sys_user_role
SET weight = #{weight}
WHERE role_id = #{roleId}
  AND user_id = #{userId}

mapper.select:
SELECT ur.user_id FROM sys_user_role ur JOIN sys_user u ON u.user_id = ur.user_id WHERE ur.role_id IN
#{rid}
AND u.del_flag = '0' AND u.status = '0'
AND ur.user_id <> #{starterId}
GROUP BY ur.user_id ORDER BY MAX(IFNULL(ur.weight, 0)) DESC,MAX(u.update_time) DESC, ur.user_id ASC LIMIT 1
